package com.kev.fortniteautobot;
import java.util.Random;
public final class CoreTest {
 static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
 public static void main(String[]args){
  TriggerGate g=new TriggerGate();check(!g.observe(true,true,0),"one frame");check(!g.observe(true,true,250),"two frames");check(g.observe(true,true,500),"three matches trigger");
  for(int t=750;t<10000;t+=250)check(!g.observe(true,true,t),"held picture must not repeat");
  g.interrupt();check(!g.observe(true,true,11000),"interrupt preserves appearance latch");
  g.observe(true,false,11250);g.observe(true,false,11500);g.observe(false,false,11750);g.observe(true,false,12000);
  check(!g.observe(true,true,12250),"invalid frame breaks disappearance evidence");
  g.observe(true,false,12500);g.observe(true,false,12750);g.observe(true,false,13000);g.observe(true,true,13250);g.observe(true,true,13500);check(g.observe(true,true,13750),"new appearance triggers");
  TriggerGate fresh=new TriggerGate();fresh.observe(true,true,0);fresh.observe(true,true,250);check(!fresh.observe(true,true,3000),"gap breaks matching evidence");check(!fresh.observe(true,true,3000),"same frame ignored");fresh.observe(true,true,3250);check(fresh.observe(true,true,3500),"fresh evidence triggers");
  TriggerGate ready=new TriggerGate(),leave=new TriggerGate(),party=new TriggerGate();for(int t=0;t<500;t+=250){ready.observe(true,true,t);leave.observe(true,false,t);party.observe(true,false,t);}check(ready.observe(true,true,500),"Ready independent");check(!leave.observe(true,false,500),"Leave not triggered by Ready");check(!party.observe(true,false,500),"Party not triggered by Ready");
  int[]a=new int[1152],b=new int[1152],flat=new int[1152];Random random=new Random(42);for(int i=0;i<a.length;i++){a[i]=random.nextInt(256);b[i]=255-a[i];flat[i]=120;}
  check(MatchMath.compare(a,a)>0.9999,"identical textured patch matches");check(MatchMath.compare(a,b)<0.01,"opposite picture rejected");check(MatchMath.compare(flat,flat)==0,"flat/black pictures cannot match");check(MatchMath.hasDetail(a)&&!MatchMath.hasDetail(flat),"diagnostics distinguishes a flat area from a usable template");
  check(!MatchMath.unit(Double.NaN)&&!MatchMath.unit(Double.POSITIVE_INFINITY)&&!MatchMath.unit(-0.1),"nonfinite/outside tap rejected");check(MatchMath.region(new double[]{0.1,0.1,0.2,0.2}),"valid region");check(!MatchMath.region(new double[]{0.9,0.1,0.2,0.2}),"outside region rejected");
  check(MatchMath.drop(540,828,1080,1080,3),"bottom-center dismiss target");check(!MatchMath.drop(80,1000,1080,1080,3),"bottom corner does not dismiss");check(!MatchMath.drop(540,300,1080,1080,3),"middle does not dismiss");check(MatchMath.clamp(990,1000,66)==934,"edge clamping");
  float[]fit=PreviewGeometry.fit(2400,1080,1000,300);check(Math.abs(fit[0]-166.6667f)<0.01,"preview excludes side letterboxing");check(Math.abs(PreviewGeometry.normal(500,fit[0],fit[2])-0.5f)<0.0001,"centre maps to centre");check(PreviewGeometry.normal(fit[0],fit[0],fit[2])==0,"left image edge maps to zero");check(PreviewGeometry.normal(fit[0]+fit[2],fit[0],fit[2])==1,"right image edge maps to one");check(PreviewGeometry.importSize(2400,1080)&&!PreviewGeometry.importSize(0,1080)&&!PreviewGeometry.importSize(30000,30000),"safe import dimensions");
  check(VariantPolicy.choose(new double[]{.95,.95},new double[]{.9,.9},-1)==0,"ties choose first saved screen");check(VariantPolicy.choose(new double[]{.94,.96},new double[]{.9,.9},0)==0,"near ties keep current choice stable");check(VariantPolicy.choose(new double[]{.81,.97},new double[]{.9,.9},0)==1,"changed screen selects its own map");check(VariantPolicy.choose(new double[]{.85,.80},new double[]{.9,.9},-1)==-1,"no matching screen does not tap");
  TriggerGate shared=new TriggerGate();shared.observe(true,true,0);shared.observe(true,true,250);check(shared.observe(true,true,500),"one chosen recording triggers");for(int t=750;t<6000;t+=250)check(!shared.observe(true,true,t),"another matching variant cannot trigger a second sequence");
  double[] protectedArea=DebugGeometry.protect(new double[]{.2,.3,.1,.1},2400,1080);check(protectedArea[0]<480&&protectedArea[2]>720&&protectedArea[1]<324,"debug excludes sampled pixels plus interpolation margin");java.util.List<double[]>obstacles=new java.util.ArrayList<>();obstacles.add(new double[]{500,0,1000,300});check(DebugGeometry.corner(1000,600,300,200,obstacles)==1,"debug HUD avoids occupied top-right corner");
  double savedX=TapCoordinates.normalize(1920,2400),savedY=TapCoordinates.normalize(702,1080);check(TapCoordinates.pixel(savedX,2400)==1920&&TapCoordinates.pixel(savedY,1080)==702,"record and replay share the captured landscape plane");check(TapCoordinates.pixel(savedX,2400)!=TapCoordinates.pixel(savedX,1080),"stale portrait service metrics must not determine gesture pixels");check(TapCoordinates.preview(savedX,100,800)==740,"numbered marker maps the same saved coordinate into a letterboxed preview");check(TapCoordinates.pixel(1,2400)==2399,"edge tap stays inside display");check(TapCoordinates.pixel(.1,2400)==240,"tap can be anywhere, independently of watch zone");
  System.out.println("CoreTest PASS: recognition, variants, coordinate round-trip, stale service-size regression, numbered preview mapping, debug geometry.");
 }
}
